import qrcode from './qrcode.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export function inviteUrl(g,origin=location.origin){const u=new URL('/',origin);u.searchParams.set('convite',g.token);return u.href}
export function fileName(g){return 'convite-'+g.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,70)+'-'+g.token.slice(-6)}
function lines(name,max=45){const out=[];for(const word of String(name).split(/\s+/)){if(out.length&&out.at(-1).length+word.length+1<=max)out[out.length-1]+=' '+word;else out.push(word)}return out}
export function qrSvg(url,x=310,y=835,size=180){const qr=qrcode(0,'M');qr.addData(url);qr.make();const n=qr.getModuleCount(),unit=size/(n+8);let d='';for(let row=0;row<n;row++)for(let col=0;col<n;col++)if(qr.isDark(row,col))d+=`M${col+4} ${row+4}h1v1h-1z`;return `<g transform="translate(${x} ${y})"><rect width="${size}" height="${size}" fill="white"/><path transform="scale(${unit})" d="${d}" fill="#291b16"/></g>`}
export function invitationSvg(g,origin=location.origin){if(g.is_placeholder)throw new Error('Indique o nome antes de gerar o convite.');const url=inviteUrl(g,origin),names=lines(g.name+(g.companion?' & '+g.companion:''));const step=Math.min(32,180/names.length);const text=(y,t,size=24,extra='')=>`<text x="400" y="${y}" text-anchor="middle" font-size="${size}" ${extra}>${escape(t)}</text>`;
return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="100mm" height="150mm" viewBox="0 0 800 1200"><title>${escape('Convite de '+g.name+(g.companion?' e '+g.companion:''))}</title><rect width="800" height="1200" fill="#f3e9d9"/><rect x="28" y="28" width="744" height="1144" fill="none" stroke="#b18a58" stroke-width="2"/><rect x="39" y="39" width="722" height="1122" fill="none" stroke="#b18a58" stroke-opacity=".4"/><g fill="none" stroke="#b18a58" stroke-width="2"><path d="M66 178Q80 90 170 65M630 1135Q720 1110 734 1022"/><path d="M75 133Q35 112 62 80Q99 103 75 133ZM98 96Q94 51 132 62Q134 96 98 96ZM110 85Q140 112 164 81Q143 58 110 85M725 1067Q765 1088 738 1120Q701 1097 725 1067ZM702 1104Q706 1149 668 1138Q666 1104 702 1104Z" fill="#d8cbbb"/></g><g fill="#543419" font-family="Georgia,serif">${text(107,'CONVITE DE CASAMENTO',18,'letter-spacing="5"')}${text(193,'Aniceta & Kerusso',54,'font-style="italic"')}${text(231,'Aniceta Martins & Kerusso Truth Perhay',18)}<path d="M260 264h280" stroke="#b18a58"/>${text(300,'20 de Fevereiro de 2027',26)}${names.map((n,i)=>text(335+i*step,n,Math.min(27,step-4),'font-style="italic"')).join('')}${text(335+names.length*step,g.companion?'Este convite é para vocês.':'Este convite é para você.',19)}${text(545,'CERIMÓNIA',18,'letter-spacing="3"')}${text(580,'Igreja Arco-Íris de Zimpeto',26)}${text(614,'10h00',24)}<path d="M330 646h140" stroke="#b18a58"/>${text(691,'RECEPÇÃO',18,'letter-spacing="3"')}${text(726,'Cajada 1 · 13h00',26)}${text(760,'Av. Dom Alexandre, paragem Tomás (Habel Jafar)',17)}${text(794,'Localização: Manuel Olgário · +258 87 879 8287',15)}${qrSvg(url)}${text(1050,'Abra o convite e confirme a sua presença',19,'fill="#7f6c5d"')}<a xlink:href="${escape(url)}"><rect x="310" y="835" width="180" height="180" fill="transparent"/></a>${text(1090,g.companion?'Convite pessoal e intransferível · 2 pessoas':'Convite pessoal e intransferível · 1 pessoa',16)}${text(1124,'Com carinho, Aniceta & Kerusso',21,'font-style="italic"')}</g></svg>`}
function save(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
export function downloadSvg(g){save(new Blob([invitationSvg(g)],{type:'image/svg+xml'}),fileName(g)+'.svg')}
export async function downloadPng(g){const blob=new Blob([invitationSvg(g)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);try{const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=1181;canvas.height=1772;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const png=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!png)throw new Error('Não foi possível gerar a imagem.');save(await png300dpi(png),fileName(g)+'.png')}finally{URL.revokeObjectURL(url)}}
export function printInvitations(guests){const ready=guests.filter(g=>g.active&&!g.is_placeholder);if(!ready.length)throw new Error('Não há convites activos com nomes para imprimir.');const w=window.open('','_blank');if(!w)throw new Error('Permita a abertura da janela de impressão no seu navegador.');w.document.open();w.document.write(`<!doctype html><html lang="pt-MZ"><head><meta charset="utf-8"><title>Convites · Aniceta & Kerusso</title><style>@page{size:100mm 150mm;margin:0}*{box-sizing:border-box}body{margin:0;background:#ece4d7;font:15px Georgia,serif}header{text-align:center;padding:24px}button{padding:12px 24px;border:0;border-radius:5px;background:#543419;color:#fff;cursor:pointer}.sheet{width:100mm;height:150mm;break-after:page;page-break-after:always;margin:20px auto;box-shadow:0 5px 20px #0003}.sheet:last-child{break-after:auto;page-break-after:auto}.sheet svg{display:block;width:100%;height:100%}@media print{body{background:none}header{display:none}.sheet{margin:0;box-shadow:none;print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style></head><body><header><p>${ready.length} convites · 10 × 15 cm</p><button id="print">Imprimir / guardar em PDF</button><p>Na impressão, seleccione escala 100%, sem margens e sem cabeçalhos.</p></header>${ready.map(g=>'<section class="sheet">'+invitationSvg(g)+'</section>').join('')}</body></html>`);w.document.close();w.document.querySelector('#print').onclick=()=>w.print();}
// ZIP with stored entries: no remote conversion, names and links remain in this browser.
function crc32(bytes){let crc=-1;for(const b of bytes){crc^=b;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0)}return (crc^-1)>>>0}
function header(size){return {bytes:new Uint8Array(size),get view(){return new DataView(this.bytes.buffer)}}}
export function zipFiles(files){const encoder=new TextEncoder(),parts=[],central=[];let offset=0,centralSize=0;for(const [filename,text]of files){const name=encoder.encode(filename),data=encoder.encode(text),crc=crc32(data),h=header(30),c=header(46);h.view.setUint32(0,0x04034b50,true);h.view.setUint16(4,20,true);h.view.setUint16(6,0x800,true);h.view.setUint32(14,crc,true);h.view.setUint32(18,data.length,true);h.view.setUint32(22,data.length,true);h.view.setUint16(26,name.length,true);c.view.setUint32(0,0x02014b50,true);c.view.setUint16(4,20,true);c.view.setUint16(6,20,true);c.view.setUint16(8,0x800,true);c.view.setUint32(16,crc,true);c.view.setUint32(20,data.length,true);c.view.setUint32(24,data.length,true);c.view.setUint16(28,name.length,true);c.view.setUint32(42,offset,true);parts.push(h.bytes,name,data);central.push(c.bytes,name);offset+=30+name.length+data.length;centralSize+=46+name.length}const end=header(22);end.view.setUint32(0,0x06054b50,true);end.view.setUint16(8,files.length,true);end.view.setUint16(10,files.length,true);end.view.setUint32(12,centralSize,true);end.view.setUint32(16,offset,true);return new Blob([...parts,...central,end.bytes],{type:'application/zip'})}
export function downloadAll(guests){const ready=guests.filter(g=>g.active&&!g.is_placeholder);if(!ready.length)throw new Error('Não há convites activos com nomes para baixar.');const files=ready.map(g=>[fileName(g)+'.svg',invitationSvg(g)]);files.push(['links-dos-convites.txt',ready.map(g=>g.name+(g.companion?' & '+g.companion:'')+'\n'+inviteUrl(g)).join('\n\n')]);save(zipFiles(files),'convites-aniceta-kerusso.zip')}

async function png300dpi(blob){const input=new Uint8Array(await blob.arrayBuffer()),view=new DataView(input.buffer),type=new TextEncoder().encode('pHYs'),data=new Uint8Array(9),d=new DataView(data.buffer);d.setUint32(0,11811);d.setUint32(4,11811);data[8]=1;const chunk=new Uint8Array(21),v=new DataView(chunk.buffer);v.setUint32(0,9);chunk.set(type,4);chunk.set(data,8);v.setUint32(17,crc32(chunk.subarray(4,17)));const parts=[input.subarray(0,8)];let added=false;for(let pos=8;pos<input.length;){const length=view.getUint32(pos),end=pos+12+length,tag=String.fromCharCode(...input.subarray(pos+4,pos+8));if(tag==='IDAT'&&!added){parts.push(chunk);added=true}if(tag!=='pHYs')parts.push(input.subarray(pos,end));pos=end}return new Blob(parts,{type:'image/png'})}
